import {normalizeInstagramReelURL, REEL_CATEGORIES} from './instagram.js';

const TAB_NAMES = {overview:'Overview',events:'Events',members:'Members',orders:'Food orders',menu:'Food menu',vendors:'Food counters',committee:'Committee',partners:'Partners',gallery:'Gallery',reels:'Instagram reels',content:'Content',wall:'Adda wall',volunteers:'Volunteers',inbox:'Inbox',reports:'Reports',roles:'Team & access',settings:'Settings'};
const NAV = [['overview','layout-dashboard'],['events','calendar'],['members','users'],['orders','shopping-bag'],['menu','utensils'],['vendors','utensils'],['gallery','image'],['reels','play'],['content','file-text'],['wall','heart'],['committee','users'],['partners','briefcase'],['volunteers','heart'],['inbox','mail'],['reports','chart-no-axes-combined'],['roles','shield'],['settings','settings']];
const UI = {query:'',filter:'all',lastTab:'',checkResult:null,vendorEvent:'all'};
const FOOD_UI = {user:'',event:'all',vendor:'all',query:'',view:'active',auto:true,updated:null,lookup:null,lookupError:''};
let staffTimer, stopScanner = () => {};
const FOOD_ROLES = ['super_admin','admin','food_vendor_manager','kitchen_staff','pickup_staff'];
const rolesOf = s => s.roles || s.auth?.roles || [];
const isAdministrator = s => rolesOf(s).some(r=>['super_admin','admin'].includes(r));
const canKitchen = s => isAdministrator(s)||rolesOf(s).some(r=>['food_vendor_manager','kitchen_staff'].includes(r));
const canCashier = s => isAdministrator(s)||rolesOf(s).some(r=>['food_vendor_manager','pickup_staff'].includes(r));
const canCancelFood = s => isAdministrator(s)||rolesOf(s).includes('food_vendor_manager');
const cancellableFood = o => o.status==='confirmed'&&(!paidOrder(o)||o.rawPaymentStatus==='complimentary'||o.paymentStatus==='complimentary');
const serviceIssue = (s,o) => s.events?.find(e=>e.id===o?.eventId)?.status==='published'?'':'This event is not open for food service. Contact the organiser.';
const paidOrder = o => ['paid','complimentary'].includes(o.paymentStatus);
const expiredOrder = o => o.status==='expired'||(o.status==='confirmed'&&!paidOrder(o)&&o.expiresAt&&Date.parse(o.expiresAt)<=Date.now());
const cashDue = o => Number(o.total??o.totalJPY??0);
const stallName = (s,id) => (s.vendors||[]).find(v=>v.id===id)?.name || 'Assigned food stall';
export function scopedFoodOrders(s) {
 const assignment=s.staffAssignment;
 return (s.orders||[]).filter(o=>isAdministrator(s)||(assignment?.eventIds||[]).includes(o.eventId)&&(assignment?.vendorIds||[]).includes(o.vendorId));
}
export function pickupEligibility(order) {
 if(!order)return 'Order not found.';
 if(order.status==='collected')return 'This ticket has already been collected.';
 if(order.status==='cancelled'||expiredOrder(order))return 'This ticket is cancelled or expired.';
 if(order.status!=='ready')return 'This order is not ready for collection yet.';
 if(!paidOrder(order))return 'Record the cash payment before handing over the food.';
 return '';
}
const MAX_UPLOAD_BYTES = 5 * 1024 * 1024;
function validImage(value){
 const source=String(value||'').trim();
 if(!source)return true;
 if(/^assets\/[A-Za-z0-9_./-]+$/.test(source)&&!source.split('/').includes('..'))return true;
 try{const url=new URL(source);return url.protocol==='https:'&&Boolean(url.hostname)&&!url.username&&!url.password;}catch{return false;}
}
const safeImage = value => validImage(value)&&String(value||'').trim() ? String(value).trim() : 'assets/reference-flowers.webp';
const imageError = 'Upload a JPG, PNG or WebP smaller than 5 MB, or use an HTTPS image URL.';
const errorMessage = (c,error) => c.auth?.friendlyError?.(error) || error?.message || 'This action could not be completed.';
function accessMessage(c,roles){const s=c.store.getState();if(s.auth?.user && roles.some(role=>(s.roles||s.auth.roles||[]).includes(role)))return '';return `<section class="page-container empty-state"><p class="eyebrow">COMMUNITY WORKSPACE</p><h1>${s.auth?.user?'Team access required.':'Sign in to continue.'}</h1><p>${s.auth?.user?'This workspace is available to assigned TIU BSS organisers. Your member account remains available from My profile.':'Use the account assigned to your organising team.'}</p><a class="btn btn-primary" href="#/${s.auth?.user?'profile':'signin'}">${s.auth?.user?'My profile':'Sign in'}</a><a class="btn btn-secondary" href="#/">Back to our home</a></section>`;}
const yen = n => `¥${Number(n||0).toLocaleString('en-US')}`;
const arr = (s,k) => Array.isArray(s[k]) ? s[k] : [];
const tabFromHash = () => (location.hash.split('/')[2] || 'overview');
const dateText = val => {if(!val)return 'Date to be confirmed';const d=new Date(val.length===10?val+'T12:00:00':val);return Number.isNaN(d.getTime())?val:d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});};
const statusClass = status => ['published','active','approved','confirmed','collected','paid','checked-in'].includes(status)?'success':['cancelled','rejected','sold-out'].includes(status)?'danger':['pending','preparing','unpaid','due'].includes(status)?'warning':'neutral';
const badge = (c,label) => `<span class="badge badge-${statusClass(label)}">${c.esc(String(label||'draft').replaceAll('-',' '))}</span>`;
const btn = (c,label,action,id='',extra='',cls='btn btn-secondary') => `<button type="button" class="${cls}" data-admin-action="${action}" data-id="${c.esc(id)}" ${extra}>${label}</button>`;
const empty = (title,note='') => `<div class="empty-state"><span class="empty-state-symbol">◇</span><h3>${title}</h3>${note?`<p>${note}</p>`:''}</div>`;
const table = (headers,rows) => `<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const panel = (title,content,extra='') => `<section class="panel"><div class="panel-heading"><h2>${title}</h2>${extra}</div>${content}</section>`;
const moneyTotal = orders => orders.filter(o=>o.status!=='cancelled').reduce((n,o)=>n+Number(o.total||0),0);
const eventName = (s,id) => arr(s,'events').find(e=>e.id===id)?.title || 'Event';
const filtered = items => items.filter(item=>(UI.filter==='all'||item.status===UI.filter||item.category===UI.filter||item.type===UI.filter)&&JSON.stringify(item).toLowerCase().includes(UI.query.toLowerCase()));
const filterBar = (c,placeholder,statuses=[]) => `<div class="toolbar"><label class="admin-search"><span>${c.icon('search')}</span><input aria-label="${placeholder}" data-admin-search placeholder="${placeholder}" value="${c.esc(UI.query)}"></label>${statuses.length?`<select aria-label="Filter results" data-admin-filter><option value="all">All statuses</option>${statuses.map(x=>`<option value="${x}" ${UI.filter===x?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select>`:''}</div>`;
function overview(c,s){
 const events=arr(s,'events'),members=arr(s,'members'),orders=arr(s,'orders'),tickets=arr(s,'tickets');
 const active=events.filter(e=>e.status==='published'),pending=members.filter(m=>m.status==='pending');
 const statData=[['Community members',members.length,`${pending.length} awaiting approval`,'users'],['Published events',active.length,'Culture, connection, community','calendar'],['Event registrations',tickets.filter(t=>t.status!=='cancelled').length,`${tickets.filter(t=>t.checkedInAt).length} checked in`,'ticket'],['Food order value',yen(moneyTotal(orders)),`${orders.filter(o=>o.status==='ready').length} orders ready for pickup`,'shopping-bag']];
 return `<div class="stat-grid">${statData.map(([label,value,note,ico])=>`<div class="stat-card"><div class="stat-card-top"><span>${label}</span>${c.icon(ico)}</div><strong>${value}</strong><small>${note}</small></div>`).join('')}</div><div class="admin-two-col">${panel('Your upcoming events',active.length?active.slice(0,4).map(e=>`<div class="admin-event-row"><div class="admin-date"><strong>${new Date(e.date+'T12:00:00').getDate()||'—'}</strong><span>${new Date(e.date+'T12:00:00').toLocaleDateString('en-US',{month:'short'})}</span></div><div><strong>${c.esc(e.title)}</strong><p>${c.esc(e.location||'Location to be announced')} · ${arr(s,'tickets').filter(t=>t.eventId===e.id&&t.status!=='cancelled').length}/${e.capacity||'∞'} guests</p></div>${btn(c,'Manage','edit-event',e.id,'','btn btn-ghost')}</div>`).join(''):empty('No published events','Create an event to bring your community together.'),`<a href="#/admin/events" class="text-link">View all →</a>`)}${panel('A little attention needed',`<div class="admin-todo"><span>${c.icon('users')}</span><div><strong>${pending.length} membership requests</strong><p>Welcome the newest members of your community.</p></div><a href="#/admin/members" aria-label="Review membership requests">→</a></div><div class="admin-todo"><span>${c.icon('utensils')}</span><div><strong>${orders.filter(o=>['confirmed','preparing'].includes(o.status)).length} kitchen orders</strong><p>Keep the food flowing at your next gathering.</p></div><a href="#/staff/food" aria-label="Open kitchen">→</a></div><div class="admin-todo"><span>${c.icon('mail')}</span><div><strong>${arr(s,'messages').filter(m=>m.status!=='read').length} messages</strong><p>Questions and ideas from the community.</p></div><a href="#/admin/inbox" aria-label="Read inbox">→</a></div>`)}</div>${panel('Workspace activity',arr(s,'audits').length?`<div class="activity-list">${arr(s,'audits').slice(0,5).map(a=>`<div><span class="activity-dot"></span><p>${c.esc(a.message||(a.action||'Workspace updated').replaceAll('_',' '))}<small>${dateText(a.createdAt||a.timestamp)}</small></p><span class="badge">Recorded</span></div>`).join('')}</div>`:empty('Your workspace is ready','Edits, registrations and orders will appear here.'))}`;
}
function eventList(c,s){
 const events=filtered(arr(s,'events'));
 return filterBar(c,'Search events…',['draft','published','cancelled'])+panel('All events',events.length?table(['Event','Date & location','Registrations','Status','Actions'],events.map(e=>`<tr><td><div class="table-title">${e.image?`<img class="table-thumb" src="${c.esc(safeImage(e.image))}" alt="" loading="lazy">`:''}<div><strong>${c.esc(e.title)}</strong><small>${c.esc(e.category||'Community')} · ${Number(e.price)?yen(e.price):'Free admission'}</small></div></div></td><td>${dateText(e.date)}<small>${c.esc(e.location||'TBA')}</small></td><td>${arr(s,'tickets').filter(t=>t.eventId===e.id&&t.status!=='cancelled').length} / ${e.capacity||'∞'}</td><td>${badge(c,e.status)}</td><td><div class="table-actions">${btn(c,'Edit','edit-event',e.id)}${e.status==='draft'?btn(c,'Publish','publish-event',e.id):`<a class="btn btn-ghost" href="#/events/${c.esc(e.slug||e.id)}">View</a>`}</div></td></tr>`)):empty('No events found','Try another search or create your first event.'),btn(c,'+ Create event','new-event','','','btn btn-primary'));
}
function memberList(c,s){
 const members=filtered(arr(s,'members'));
 return filterBar(c,'Search names, universities or skills…',['active','pending','approved','rejected'])+panel('Community directory',members.length?table(['Member','Studies / work','Location','Status','Actions'],members.map(m=>`<tr><td><div class="table-title"><span class="admin-avatar">${c.esc((m.name||'?').split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><strong>${c.esc(m.name)}</strong><small>${c.esc(m.type||'Member')}</small></div></div></td><td>${c.esc(m.university||m.employer||'Not provided')}<small>${c.esc(m.major||m.jobTitle||m.role||'')}</small></td><td>${c.esc(m.city||'—')}</td><td>${badge(c,m.status||'active')}</td><td><div class="table-actions">${btn(c,'Details','member-detail',m.id)}${m.status==='pending'?btn(c,'Approve','approve-member',m.id,'','btn btn-primary'):''}</div></td></tr>`)):empty('No members found','Try a different name or status.'),btn(c,'Export CSV','export','','data-collection="members"'));
}
function orderActions(c,o){
 const s=c.store.getState();
 if(['cancelled','collected','expired'].includes(o.status)||expiredOrder(o))return `<span class="form-help">${expiredOrder(o)?'Reservation expired':'Closed ticket'}</span>`;
 if(serviceIssue(s,o))return `<p class="form-help">${c.esc(serviceIssue(s,o))}</p>${cancellableFood(o)&&canCancelFood(s)?btn(c,'Cancel reservation','cancel-order',o.id):''}`;
 return `<div class="table-actions">${o.status==='confirmed'&&canKitchen(s)?btn(c,'Start preparing','order-action',o.id,'data-next="prepare"','btn btn-primary'):''}${o.status==='preparing'&&canKitchen(s)?btn(c,'Mark ready','order-action',o.id,'data-next="ready"','btn btn-primary'):''}${!paidOrder(o)&&canCashier(s)?btn(c,`Record ${yen(cashDue(o))} cash`,'cash-order',o.id):''}${o.status==='ready'&&paidOrder(o)&&canCashier(s)?btn(c,'Manual collection','pickup-order',o.id,'','btn btn-secondary'):''}${cancellableFood(o)&&canCancelFood(s)?btn(c,'Cancel','cancel-order',o.id,'','btn btn-ghost'):''}</div>`;
}
function orderList(c,s){
 const orders=filtered(arr(s,'orders')).slice().sort((a,b)=>Date.parse(b.createdAt||0)-Date.parse(a.createdAt||0));
 return filterBar(c,'Search order ID or food…',['confirmed','preparing','ready','collected','cancelled'])+panel('Orders & pickup',`<p class="panel-note">One ticket belongs to one stall. Record cash only after receiving it, then verify the pickup ticket before handing over food.</p>${orders.length?table(['Order / stall','Items','Total','Payment','Status','Actions'],orders.map(o=>`<tr><td><strong>${c.esc(o.orderNumber||o.id)}</strong><small>${c.esc(eventName(s,o.eventId))} · ${c.esc(stallName(s,o.vendorId))}</small><small>${c.esc(o.pickup||o.pickupLocation||'Event collection')}</small></td><td>${(o.items||[]).map(i=>`${i.qty??i.quantity} × ${c.esc(i.name)}`).join('<br>')}</td><td>${yen(cashDue(o))}</td><td>${badge(c,o.rawPaymentStatus||o.paymentStatus||'unpaid')}</td><td>${badge(c,expiredOrder(o)?'expired':o.status)}</td><td>${orderActions(c,o)}</td></tr>`)):empty('No food orders yet','Orders placed through an event menu will appear here.')}`,`<a class="btn btn-secondary" href="#/staff/food">Open stall counter →</a>`);
}
