function checkResult(result){if(result===false)throw Error('This change could not be completed.');if(result&&typeof result==='object'&&(result.ok===false||result.success===false||result.error)){throw Error(typeof result.error==='string'?result.error:result.message||'This change could not be completed.');}return result;}
function confirmAction(c,title,message,onConfirm){c.modal(title,`<p>${message}</p><div class="modal-actions"><button class="btn btn-secondary" type="button" id="admin-confirm-cancel">Keep current data</button><button class="btn btn-danger" type="button" id="admin-confirm-yes">Confirm</button></div>`,()=>{document.getElementById('admin-confirm-cancel')?.addEventListener('click',c.closeModal);document.getElementById('admin-confirm-yes')?.addEventListener('click',async event=>{const button=event.currentTarget;if(button.disabled)return;button.disabled=true;try{await onConfirm();c.closeModal();c.render();}catch(err){c.toast(errorMessage(c,err));}finally{button.disabled=false;}});});}
async function downloadCSV(c,collection){
 const csv=await c.store.exportCSV(collection);if(typeof csv!=='string')throw Error('CSV export is not available.');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`tiu-bss-${collection}-${new Date().toISOString().slice(0,10)}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);c.toast('CSV downloaded.');
}
function orderById(c,id){return arr(c.store.getState(),'orders').find(o=>o.id===id)||(FOOD_UI.lookup?.order.id===id?FOOD_UI.lookup.order:null);}
async function refreshFood(c){await (c.store.refreshOrders?c.store.refreshOrders():c.store.refresh());FOOD_UI.updated=c.store.getState().ordersUpdatedAt||new Date().toISOString();c.render();}
function confirmCash(c,id){
 const order=orderById(c,id);if(!order)throw Error('Refresh the queue and find this order again.');
 if(!canCashier(c.store.getState()))throw Error('Cash collection requires counter or pickup access.');
 const issue=serviceIssue(c.store.getState(),order);if(issue)throw Error(issue);
 if(paidOrder(order))throw Error('Payment is already recorded for this ticket.');
 if(['cancelled','collected'].includes(order.status)||expiredOrder(order))throw Error('This ticket cannot receive payment.');
 const due=cashDue(order);
 c.modal('Record cash received',`<form id="stall-cash-form"><p class="eyebrow">${c.esc(stallName(c.store.getState(),order.vendorId))}</p><h3>${yen(due)} due</h3><p>For ticket <strong>${c.esc(order.orderNumber||order.id)}</strong>. This records cash handed to the stall; it does not charge a card.</p>${field(c,'Cash received (JPY)','tendered','','number',`required min="${due}" step="1" inputmode="numeric"`)}<p class="stall-cash-change" data-cash-change>Change: —</p><label class="check-field"><input name="received" type="checkbox" required> I have received and counted the cash.</label><p class="form-error" data-cash-error role="alert"></p><div class="modal-actions"><button class="btn btn-secondary" type="button" data-cash-cancel>Cancel</button><button class="btn btn-primary" type="submit">Record ${yen(due)} received</button></div></form>`,()=>{
  const form=document.getElementById('stall-cash-form');if(!form)return;
  const amount=form.elements.namedItem('tendered');amount.addEventListener('input',()=>{const value=Number(amount.value);form.querySelector('[data-cash-change]').textContent=amount.value&&Number.isInteger(value)&&value>=due?`Change to return: ${yen(value-due)}`:'Change: —';});
  form.querySelector('[data-cash-cancel]').addEventListener('click',c.closeModal);
  form.addEventListener('submit',async event=>{event.preventDefault();if(form.dataset.busy==='true')return;const submit=form.querySelector('[type="submit"]'),error=form.querySelector('[data-cash-error]');error.textContent='';try{
   const value=Number(amount.value);if(!Number.isInteger(value)||value<due||!form.elements.namedItem('received').checked)throw Error('Enter the cash received and confirm you have counted it.');
   form.dataset.busy='true';submit.disabled=true;checkResult(await c.store.advanceOrder(id,'confirmPayment',{amountJPY:due,manual:true}));c.closeModal();c.toast(`Cash payment recorded. Return ${yen(value-due)} change.`);c.render();
  }catch(cause){error.textContent=errorMessage(c,cause);}finally{form.dataset.busy='false';submit.disabled=false;}});
 });
}
function confirmPickup(c,id,lookup=null){
 const order=orderById(c,id);const reason=serviceIssue(c.store.getState(),order)||pickupEligibility(order);if(reason)throw Error(reason);
 if(!canCashier(c.store.getState()))throw Error('Pickup access is required to hand over an order.');
 const manual=lookup?.manual!==false,token=manual?undefined:lookup?.token;
 if(!manual&&!token)throw Error('Scan the customer’s food pickup ticket again.');
 c.modal(manual?'Confirm manual collection':'Confirm ticket collection',`<form id="stall-pickup-form"><p class="eyebrow">${c.esc(stallName(c.store.getState(),order.vendorId))}</p><h3>${c.esc(order.orderNumber||order.id)}</h3><ul class="stall-handover-items">${(order.items||[]).map(i=>`<li><b>${i.qty??i.quantity} ×</b> ${c.esc(i.name)}</li>`).join('')}</ul><p>${manual?'Manual collection: compare the order reference and items with the customer’s ticket before handing over the food. This action is recorded as a manual handover.':'This pickup ticket is ready. Check the items with the customer before handing over the food.'}</p><label class="check-field"><input name="handover" type="checkbox" required> I am handing over all items on this ticket.</label><p class="form-error" data-pickup-error role="alert"></p><div class="modal-actions"><button class="btn btn-secondary" type="button" data-pickup-cancel>Not yet</button><button class="btn btn-primary" type="submit">Mark collected once</button></div></form>`,()=>{
  const form=document.getElementById('stall-pickup-form');if(!form)return;
  form.querySelector('[data-pickup-cancel]').addEventListener('click',c.closeModal);
  form.addEventListener('submit',async event=>{event.preventDefault();if(form.dataset.busy==='true')return;const button=form.querySelector('[type="submit"]'),error=form.querySelector('[data-pickup-error]');error.textContent='';try{
   if(!form.elements.namedItem('handover').checked)throw Error('Confirm the food handover first.');form.dataset.busy='true';button.disabled=true;
   checkResult(await c.store.advanceOrder(id,'pickup',{manual,...(token?{token}:{})}));FOOD_UI.lookup=null;c.closeModal();c.toast('Collected. This pickup ticket cannot be used again.');c.render();
  }catch(cause){error.textContent=errorMessage(c,cause);}finally{form.dataset.busy='false';button.disabled=false;}});
 });
}
async function findPickup(c,value,manual=false){
 const code=String(value||'').trim();if(!code)throw Error(manual?'Enter the full order reference.':'Scan or paste the food pickup ticket.');
 let token=manual?undefined:code;
 if(!manual&&code.startsWith('{')){let data;try{data=JSON.parse(code);}catch{throw Error('This pickup ticket is incomplete. Scan or copy it again.');}if(data.type!=='food'||!data.id||!data.token)throw Error('Use a food pickup ticket, not an admission ticket.');token=data.token;}
 let order;
 if(typeof c.store.lookupFoodOrder==='function')order=await c.store.lookupFoodOrder(code,{manual});
 else {await c.store.refresh();order=arr(c.store.getState(),'orders').find(o=>manual?o.id===code:(o.qrToken||o.pickupToken)===token);}
 if(!order)throw Error('No matching ticket was found in your assigned stalls. Check the code and refresh.');
 if(!scopedFoodOrders({...c.store.getState(),orders:[order]}).length)throw Error('This ticket belongs to a different stall assignment.');
 FOOD_UI.lookup={order,manual,token};FOOD_UI.lookupError='';FOOD_UI.updated=new Date().toISOString();return order;
}
async function scanPickup(c){
 if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){c.toast('Camera scanning is not supported in this browser. Paste the pickup ticket or use a handheld QR scanner.');document.querySelector('[data-food-code]')?.focus();return;}
 stopScanner();
 c.modal('Scan a food pickup ticket',`<div class="stall-camera"><video data-stall-camera autoplay muted playsinline aria-label="Pickup ticket camera"></video><p>Point the camera at the customer’s food pickup QR.</p><p class="form-error" data-camera-error role="alert"></p><button class="btn btn-secondary" data-camera-cancel>Close camera</button></div>`,async()=>{
  const video=document.querySelector('[data-stall-camera]'),error=document.querySelector('[data-camera-error]');if(!video)return;
  let stream,frame,stopped=false,detecting=false,observer;
  stopScanner=()=>{stopped=true;if(frame)cancelAnimationFrame(frame);stream?.getTracks().forEach(track=>track.stop());observer?.disconnect();};
  document.querySelector('[data-camera-cancel]')?.addEventListener('click',()=>{stopScanner();c.closeModal();});
  observer=new MutationObserver(()=>{if(!video.isConnected)stopScanner();});observer.observe(document.getElementById('modal-root')||document.body,{childList:true,subtree:true});
  try{
   const detector=new window.BarcodeDetector({formats:['qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(stopped||!video.isConnected){stream.getTracks().forEach(t=>t.stop());return;}video.srcObject=stream;await video.play();
   const scan=async()=>{if(stopped||!video.isConnected){stopScanner();return;}if(video.readyState>=2&&!detecting){detecting=true;try{const values=await detector.detect(video);if(values[0]?.rawValue){stopScanner();const raw=values[0].rawValue;c.closeModal();try{await findPickup(c,raw,false);c.render();}catch(cause){FOOD_UI.lookupError=errorMessage(c,cause);c.render();}return;}}catch(cause){error.textContent='Keep the QR inside the camera view, or close and paste the ticket.';}finally{detecting=false;}}frame=requestAnimationFrame(scan);};frame=requestAnimationFrame(scan);
  }catch(cause){stopScanner();if(error.isConnected)error.textContent='Camera access is unavailable. Close this view and paste the pickup ticket or use a handheld scanner.';}
 });
}
function exportFoodView(c){
 const {rows}=staffScope(c.store.getState());const selected=rows.filter(o=>FOOD_UI.view==='history'?(['collected','cancelled','expired'].includes(o.status)||expiredOrder(o)):!['collected','cancelled','expired'].includes(o.status)&&!expiredOrder(o));
 const cells=value=>`"${String(value??'').replace(/^[\s]*[=+\-@]/,"'$&").replaceAll('"','""')}"`;
 const values=[['Order reference','Event','Stall','Items','Total JPY','Payment','Status','Ordered at'],...selected.map(o=>[o.id,eventName(c.store.getState(),o.eventId),stallName(c.store.getState(),o.vendorId),(o.items||[]).map(i=>`${i.qty??i.quantity} x ${i.name}`).join('; '),cashDue(o),o.paymentStatus,expiredOrder(o)?'expired':o.status,o.createdAt])];
 const csv=values.map(row=>row.map(cells).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=`tiu-bss-stall-${FOOD_UI.view}-${new Date().toISOString().slice(0,10)}.csv`;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);c.toast(`${selected.length} loaded orders exported.`);
}
